      uiWhoosh() { if (!ac || muted) return; const t = ac.currentTime; nz(t, 'bandpass', 700, 0.8, 0.035, 0.28, sfx, 0.06); tone(BASE * 2, 0.02, 0.3, { bus: sfx, to: BASE * 3, glide: 0.2 }); },
