    const vmax = Math.max(ROUTE.lineSpeed, ...pts.map((p) => p[2])) * 1.08, X = (x) => pl + (Wd - pl - pr) * clamp((x - xa) / Math.max(1, xb - xa), 0, 1), Y = (v) => Hd - pb - (Hd - pt - pb) * clamp(v / vmax, 0, 1);
