    return { argo: { name: 'Argo Senja', kind: 'Kereta eksekutif' }, hst: { name: 'Kilat', kind: 'Kereta cepat' }, hst2: { name: 'Guntur', kind: 'Kereta cepat' }, steam: { name: 'Surya', kind: 'Kereta wisata' } }[MIS.loco] || { name: 'Cakra', kind: 'Kereta lokal' };
