      c.fillStyle = '#fff0c8'; c.font = BIGF(H * 0.03); c.fillText(txt, gx, gy + r + H * 0.02);
      c.fillStyle = '#e8cf9a'; c.font = FNT(800, H * 0.017); c.fillText(label, gx, gy + r + H * 0.04);
