    const k0 = MIS.dark ? 1.05 : V.night ? 0.85 : 0.75, len = (V.night || MIS.dark ? 52 : 38) * ppm; // berkas malam dibuat lembut agar marka & rel di depan tetap terbaca
    // berkas lebar yang lembut (cahaya menyebar di udara lembap)
