    c.fillStyle = lgC; c.beginPath(); c.moveTo(lx, ly); c.lineTo(lx + len * 0.7, ly - 3 * ppm); c.lineTo(lx + len * 0.7, ly + 2.6 * ppm); c.closePath(); c.fill();
