    const body = new Path2D(); body.moveTo(x - w * 1.2, yb + 2);
    for (let i = 0; i <= 90; i++) { const [px, py] = pt(-1 + i / 45); body.lineTo(px, py); }
    body.lineTo(x + w * 1.2, yb + 2); body.closePath();
