      lg.addColorStop(0, 'rgba(46,34,78,0.45)'); lg.addColorStop(0.45, 'rgba(46,34,78,0.1)'); lg.addColorStop(0.55, 'rgba(255,160,120,0.14)'); lg.addColorStop(1, 'rgba(255,170,118,0.62)');
