      c.strokeStyle = 'rgba(0,0,0,0.12)'; c.lineWidth = Math.max(1, r * 0.04);
      [-0.55, 0, 0.55].forEach((k) => { c.beginPath(); c.moveTo(cx + k * r, by); c.quadraticCurveTo(cx + k * r * 1.15, by - h * 0.55, cx, by - h); c.stroke(); });
