      box(-1.9, 24, 3.8, 2.4, '#2b3a44'); poly([[-2.2, 26.4], [0, 28.4], [2.2, 26.4]], '#c0392b');
      const on = night || o.storm;
      c.fillStyle = on ? '#fff2b0' : T('#f4e7a8'); c.fillRect(x - 1.4 * s, y - 26 * s, 2.8 * s, 1.6 * s);
