    const { c, ppm, gy, X, st } = V;
    const rows = 6, cell = 14, yTop = gy + 1.4 * ppm;
    const rowY = (t) => yTop + (H - yTop) * Math.pow(t, 1.55);
    const at = (sx, t) => sx + (V.Xn(sx) - sx) * Math.pow(t, 1.55);
