        const tk = k / strips, yy = y0 + tk * hgt, wob = Math.sin(tt * 3.2 + k * 1.3 + i) * (1 + r) * 1.4;
        const a = (V.night ? 0.5 : 0.46) * fade * (1 - tk * 0.55);
