      const g2 = c.createLinearGradient(lx, 0, lx + 30 * ppm, 0); g2.addColorStop(0, 'rgba(255,236,190,0.3)'); g2.addColorStop(1, 'rgba(255,236,190,0)');
      c.fillStyle = g2;
