    const basket = o.basket;
    c.fillStyle = 'rgba(20,16,10,0.22)'; c.beginPath(); c.ellipse(x - 0.35 * s, y, 0.55 * s, 0.1 * s, 0, 0, 7); c.fill(); // bayangan kontak
