    if (p.kind === 'kond') { c.fillStyle = '#1e2a3a'; c.fillRect(x - headR * 1.1, headY - headR * 1.3, headR * 2.2, headR * 0.7); c.fillStyle = '#d8b04a'; c.fillRect(x - headR * 0.3, headY - headR * 1.15, headR * 0.6, headR * 0.3); }
