      for (let q = 1; q < 7; q++) { const yy = 7.5 + q * 0.34, ins = q * 0.34 * 0.75; c.moveTo(px(-3.4 + ins), py(yy)); c.lineTo(px(3.4 - ins), py(yy)); } c.stroke();
      rect(-6.0, 6.22, 6.0, 6.4, '#f3ead6');
