  function locoWheel(c, x, y, r, ang) {
    c.fillStyle = '#15181b'; c.beginPath(); c.arc(x, y, r * 1.07, 0, 7); c.fill();                       // flens
    const tg = c.createLinearGradient(x - r, y - r, x + r, y + r); tg.addColorStop(0, '#9ea6ab'); tg.addColorStop(0.5, '#5b6369'); tg.addColorStop(1, '#3a4045');
    c.fillStyle = tg; c.beginPath(); c.arc(x, y, r, 0, 7); c.fill();                                     // ban baja
    const wg = c.createRadialGradient(x - r * 0.25, y - r * 0.25, r * 0.1, x, y, r * 0.84); wg.addColorStop(0, '#454c52'); wg.addColorStop(1, '#1f2327');
    c.fillStyle = wg; c.beginPath(); c.arc(x, y, r * 0.84, 0, 7); c.fill();                              // bidang roda
    c.strokeStyle = 'rgba(200,208,214,0.35)'; c.lineWidth = Math.max(1, r * 0.05); c.beginPath(); c.arc(x, y, r * 0.62, 0, 7); c.stroke();
    c.strokeStyle = 'rgba(255,255,255,0.5)'; c.lineWidth = Math.max(1, r * 0.06); c.beginPath(); c.arc(x, y, r * 0.93, Math.PI * 1.05, Math.PI * 1.6); c.stroke();
    c.strokeStyle = '#e8e2d0'; c.lineWidth = Math.max(1, r * 0.09); c.beginPath(); c.moveTo(x + Math.cos(ang) * r * 0.86, y + Math.sin(ang) * r * 0.86); c.lineTo(x + Math.cos(ang) * r * 0.99, y + Math.sin(ang) * r * 0.99); c.stroke();
    c.fillStyle = 'rgba(0,0,0,0.35)'; c.beginPath(); c.arc(x + Math.cos(ang + 2.1) * r * 0.45, y + Math.sin(ang + 2.1) * r * 0.45, r * 0.07, 0, 7); c.fill();
  }
  // roda cakram dengan tanda putar kecil supaya gerakannya terlihat
  let UPPER_PASS = false; // lintasan badan (dipadatkan): roda kecil seluruhnya di bawah garis poros, jadi tidak pernah digambar di sini (mencegah roda tampak ganda)
  // rok bogie penuh kereta cepat (gaya sebelumnya): roda tertutup rok, panel bogie sedikit lebih gelap & membulat lembut
  // dengan garis kilau tipis; hanya tepi bawah roda yang tampak di bawah rok, menapak rel
  function hstWell(c, xa, xb, Y, ppm, wheels, ang) {
    const w = xb - xa, y0 = Y(0.34), yt = Y(1.32), r = 0.3 * ppm;
    c.save(); c.beginPath(); c.rect(xa - ppm, y0, w + 2 * ppm, 0.5 * ppm); c.clip(); for (const x of wheels) trainWheel(c, x, Y(0.48), 0.46 * ppm, ang); c.restore();
    const g = c.createLinearGradient(0, yt, 0, y0); g.addColorStop(0, 'rgba(30,36,44,0.16)'); g.addColorStop(0.6, 'rgba(30,36,44,0.24)'); g.addColorStop(1, 'rgba(30,36,44,0.34)');
    c.fillStyle = g; roundRect(c, xa, yt, w, y0 - yt, r); c.fill();
    c.strokeStyle = 'rgba(255,255,255,0.55)'; c.lineWidth = Math.max(1, 0.035 * ppm); c.beginPath(); c.moveTo(xa + r, yt + 0.5); c.lineTo(xb - r, yt + 0.5); c.stroke();
    c.strokeStyle = 'rgba(60,68,78,0.35)'; c.lineWidth = 1; roundRect(c, xa + 0.5, yt + 0.5, w - 1, y0 - yt - 1, r); c.stroke();
  }
  function trainWheel(c, x, y, r, ang) {
    if (UPPER_PASS) return;
    c.fillStyle = '#2b2f32'; c.beginPath(); c.arc(x, y, r, 0, 7); c.fill();
    c.strokeStyle = '#a7adb1'; c.lineWidth = Math.max(1, r * 0.18); c.beginPath(); c.arc(x, y, r * 0.86, 0, 7); c.stroke();
    c.fillStyle = '#d7dbde';
    c.beginPath(); c.arc(x, y, r * 0.28, 0, 7); c.fill();
    c.beginPath(); c.arc(x + Math.cos(ang) * r * 0.58, y + Math.sin(ang) * r * 0.58, r * 0.13, 0, 7); c.fill();
  }

  // ornamen livery Cakra (pita emas di sisi lokomotif): kawung, parang, atau mega mendung

  // ukiran Dayak: sulur spiral berkait (satu satuan), dir = 1 atau -1 untuk dicerminkan
  // (cx, cy) pusat spiral, u = ukuran satuan (piksel)
  function dayakScroll(c, cx, cy, u, dir, col, accent) {
    c.save(); c.translate(cx, cy); c.scale(dir, 1);
    c.strokeStyle = col; c.lineCap = 'round'; c.lineJoin = 'round';
    // spiral utama
    c.lineWidth = Math.max(1, u * 0.11); c.beginPath();
    for (let k = 0; k <= 40; k++) { const t = k / 40 * Math.PI * 2.4, r = u * 0.42 * (1 - t / (Math.PI * 2.9)); const px = Math.cos(t + Math.PI) * r, py = Math.sin(t + Math.PI) * r; k ? c.lineTo(px, py) : c.moveTo(px, py); }
    c.stroke();
    // sulur besar yang menyapu ke kanan lalu berkait balik
    c.lineWidth = Math.max(1, u * 0.1); c.beginPath();
    c.moveTo(-u * 0.42, 0);
    c.bezierCurveTo(-u * 0.45, u * 0.55, u * 0.55, u * 0.6, u * 0.85, u * 0.05);
    c.bezierCurveTo(u * 1.0, -u * 0.25, u * 0.75, -u * 0.42, u * 0.6, -u * 0.22);
    c.quadraticCurveTo(u * 0.55, -u * 0.08, u * 0.7, -u * 0.06);
    c.stroke();
    // sulur kecil ke atas dengan kait (taring)
    c.lineWidth = Math.max(1, u * 0.07); c.beginPath();
    c.moveTo(u * 0.05, -u * 0.36);
    c.bezierCurveTo(u * 0.15, -u * 0.62, u * 0.5, -u * 0.62, u * 0.52, -u * 0.42);
    c.quadraticCurveTo(u * 0.5, -u * 0.32, u * 0.4, -u * 0.36);
    c.stroke();
    // duri-duri kecil di sepanjang sulur bawah
    c.lineWidth = Math.max(1, u * 0.05);
    [0.05, 0.3, 0.55].forEach((t) => { const bx = -u * 0.2 + t * u * 1.05, by = u * 0.43 - t * t * u * 0.4; c.beginPath(); c.moveTo(bx, by); c.lineTo(bx + u * 0.08, by + u * 0.14); c.stroke(); });
    if (accent) { c.fillStyle = accent; c.beginPath(); c.arc(0, 0, u * 0.08, 0, 7); c.fill(); c.beginPath(); c.arc(u * 0.68, -u * 0.12, u * 0.05, 0, 7); c.fill(); }
    c.restore();
  }
  let LOCO_ORN = 'dayak';
  let LOCO_FORCE = null; // garasi: paksa gambar lokomotif tertentu
  let LIVERY_FORCE = null; // livery pengganti untuk bentuk Guntur (mis. KA Cepat Garuda): { acc, pin, name, code, band?, body?, mask? }
  // gradasi badan Guntur (atap → rok); livery generasi baru boleh membawa warna badan sendiri
