        c.beginPath(); c.moveTo(...P(0, 0)); c.quadraticCurveTo(...P(L0 * 0.35, -w0), ...P(L0 * 0.85, -w0 * 0.25)); c.quadraticCurveTo(...P(L0 * 1.05, w0 * 0.3), ...P(L0 * 0.8, w0 * 0.45));
