      c.fillRect(x0, yTop + h * 0.02, x1 - x0, Math.max(1, u * 0.04)); c.fillRect(x0, yBot - h * 0.02 - Math.max(1, u * 0.04), x1 - x0, Math.max(1, u * 0.04)); // bingkai tipis
